    ring_entry->pos.set(
        (float)cos(angle) * 256.0f + 512.0f,
        (float)sin(angle) * 256.0f + 512.0f);
    ring_entry->template_id = SPAWN_ID_LIZARD_RANDOM_31;
    ring_entry->trigger_time_ms = trigger_time_ms;
    ring_entry->count = 1;
    ring_entry->heading =
        (float)angle_index * -0.34906587f;
    template_cursor += 6;
    trigger_time_ms += 900;
}

